from __future__ import annotations

from decimal import Decimal


def _text(value: object) -> str:
    """Return the legacy string representation for validation purposes."""
    if value is None:
        return ""
    return str(value)


def _numeric(value: object) -> Decimal:
    """Coerce legacy numeric values, treating blank values as zero."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _length(value: object) -> int:
    """Implement legacy LEN semantics for missing or null values."""
    return len(_text(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    del today  # Fixed interface parameter; none of these rules use TODAY().

    errors: list[dict] = []

    def failure(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(record.get("ACCT_NM", "")) < 2:
            failure("E1001", "Account name too short")

    # ACC-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _text(record.get("ACCT_TYP", "")) not in {"C", "P", "R", "X"}:
            failure("E1002", "Invalid account type")

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _numeric(record.get("ANN_REV", "")) < 0:
            failure("E1003", "Annual revenue negative")

    # ACC-004: UPDATE only
    if event == "UPDATE":
        previous = old if old is not None else {}
        releasing_zero_limit = (
            _text(previous.get("CRED_HOLD", "")) == "Y"
            and _text(record.get("CRED_HOLD", "")) == "N"
            and _numeric(record.get("CRED_LIMIT", "")) <= 0
        )
        if releasing_zero_limit:
            failure(
                "E1004",
                "Cannot release credit hold with zero credit limit",
            )

    # ACC-005: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(record.get("REGION_CD", "")) != 3:
            failure(
                "E1005",
                "Region code must be 3 chars",
                "WARN",
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
